import {
    FileQuestion
} from 'lucide-react';

import { DynamicForm } from '@/Components/Core/DynamicCrud/DynamicForm';
import StatusBadge from '@/Components/UI/StatusBadge';
import { useTranslations } from '@/Hooks/useTranslations';
import type { CrudConfig, CrudPageProps } from '@/Types/crud';
import { limitText } from '@/Utils/helpers';
import z from 'zod';

export function useBannerConfig(props: CrudPageProps): CrudConfig {

    const { t } = useTranslations();

    const modelProperty = props?.modelProperty;
    const advanceFilterOptions = props?.advanceFilterOptions || [];
    const routePrefix = modelProperty?.routePrefix;


    const baseBreadcrumbs = [
        { label: t('Dashboard'), href: route('backend.dashboard') },
        { label: t('Banners'), href: route(`${routePrefix}.index`) },
    ];

    return {

        formComponent: DynamicForm,
        fetchToggle: false,
        form: {
            title: {
                create: t('Create Banner'),
                edit: t('Edit Banner'),
            },
            description: {
                create: t('Add a new Banner to the system'),
                edit: t('Update Banner information'),
            },
            submitButtonText: {
                create: t('Create Banner'),
                edit: t('Update Banner'),
            },

            fields: [
                {
                    name: 'title',
                    label: t('Title'),
                    type: 'text',
                    placeholder: t('Enter title...'),
                    required: true,
                    section: 'basic',
                    gridColumn: 'span 3'
                },
                {
                    name: 'image',
                    label: t('Image'),
                    type: 'file',
                    accept: 'image/*',
                    required: true,
                    section: 'basic',
                    gridColumn: 'span 3',
                    validation: z.any().optional(),
                    icon: <FileQuestion className="w-4 h-4" />,
                    preview: true,
                    previewImgDbKey: 'image'
                },
                {
                    name: 'status',
                    label: t('Status'),
                    type: 'select',
                    required: true,
                    options: [
                        { value: 'active', label: 'Active' },
                        { value: 'inactive', label: 'Inactive' },
                    ],
                    section: 'basic',
                },


            ],
        },

        formValidationRules: {



        },

        resource: 'Banner',
        resourcePlural: 'Banners',
        title: t('Banners'),
        description: t('Manage Banners'),

        routes: {
            index: `${routePrefix}.index`,
            create: `${routePrefix}.create`,
            edit: `${routePrefix}.edit`,
            store: `${routePrefix}.store`,
            update: `${routePrefix}.update`,
            destroy: `${routePrefix}.destroy`,
        },

        formDisplayMode: 'modal',
        viewDisplayMode: 'modal',
        statusType: 'binary',

        breadcrumbs: {
            index: [
                { label: t('Dashboard'), href: route('backend.dashboard') },
                { label: t('Banners'), href: null, active: true },
            ],
            create: [
                ...baseBreadcrumbs,
                { label: t('Create'), href: null, active: true },
            ],
            update: [
                ...baseBreadcrumbs,
                { label: t('Update'), href: null, active: true },
            ],
        },

        table: {
            selectable: false,
            searchable: true,
            serializable: true,
            searchPlaceholder: t('Search Banners by question, answer...'),
            sortable: true,
            defaultSort: 'created_at',
            defaultSortDirection: 'desc',
            emptyMessage: t('No Banners available. Create your first Banner to get started.'),
            emptyMessageIcon: FileQuestion,

            columns: [
                {
                    key: 'title',
                    label: t('Title'),
                    sortable: false,
                    filterable: true,
                    priority: 0,
                    render: (row: any) => (
                        <div className="text-sm text-gray-900 dark:text-gray-100">{limitText(row.title, 20)}</div>
                    )

                },

                {
                    key: 'image',
                    label: t('Image'),
                    sortable: false,
                    priority: 1,
                    render: (row: any) => (

                        <div className="text-sm text-gray-900 dark:text-gray-100">
                            <img className="object-cover w-10 h-10" src={row.image} alt={row.title} />
                        </div>

                    )
                },


                {
                    key: 'status',
                    label: 'Status',
                    sortable: false,
                    filterable: false,
                    priority: 3,
                    render: (row: any) => {

                        return (
                            <>
                                <div className='mt-1.5'>
                                    <StatusBadge status={row.status} />
                                </div>
                            </>
                        );
                    },
                },

                {
                    key: 'created_at',
                    label: t('Created at'),
                    sortable: false,
                    priority: 4,
                    renderType: 'date',
                },
            ],

        },


        filters: {
            searchFields: ['title'],
            filterFields: advanceFilterOptions,
        },

        permissions: {
            actions: {
                create: 'banner.create',
                edit: 'banner.edit',
                view: 'banner.view',
                delete: 'banner.delete',
            },
        },

        actionConstraints: {
            delete: [
                {
                    field: 'is_owner',
                    checkValue: true,
                    message: 'Cannot delete owner account',
                },
                {
                    field: 'orders_count',
                    message: 'Cannot delete FAQ with existing orders',
                },
            ],
            bulkDelete: [
                {
                    field: 'is_owner',
                    checkValue: true,
                    message: 'Cannot delete owner account',
                },
            ],
        },

        destroyDialogConfig: {

            title: t(`Delete Banner`),
            description: t(`Are you sure you want to delete this Banner? This action cannot be undone.`),

        },

        labels: {
            singular: 'Banner',
            plural: 'Banners',
            key: 'banner',
        },

        saveAlertInfo: {
            title: t('Banner Configuration'),
            description: t('Banner configuration updated successfully.'),
        }
    }
};

